# id, cut, shot, start(s), lo, hi (shot window for the check), text, music?, claim
# lo/hi = the shot's own span in the cut [start, end]; the check requires narration to sit inside lo+0.3 .. hi-0.3
L = []
def add(cut, id, shot, lo, hi, at, text, claim, music=False):
    L.append(dict(cut=cut, id=id, shot=shot, lo=lo, hi=hi, at=at, text=text, claim=claim, music=music))

